// Normaliza la lectura entrante y prepara el body para el motor de IA
let data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('Payload MQTT no es JSON válido: ' + msg.payload);
    return null;
}

const REQUIRED = ['nivel_m','temp_ambiente_c','temp_agua_c','tds_ppm','ph','turbidez_ntu'];
const faltantes = REQUIRED.filter(k => typeof data[k] !== 'number');
if (faltantes.length > 0) {
    node.warn('Lectura descartada. Campos inválidos/faltantes: ' + faltantes.join(', '));
    return null;
}

const nodoId = msg.topic ? msg.topic.split('/').pop() : (data.node_id || 'nodo_desconocido');

const lectura = {
    nodo_id: nodoId,
    ts: Date.now(),
    nivel_m: data.nivel_m,
    temp_ambiente_c: data.temp_ambiente_c,
    temp_agua_c: data.temp_agua_c,
    tds_ppm: data.tds_ppm,
    ph: data.ph,
    turbidez_ntu: data.turbidez_ntu
};

msg.lectura = lectura;
// Body exacto que espera el esquema Pydantic SensorData del motor_ia_chancay
msg.payload = {
    nivel_m: lectura.nivel_m,
    temp_ambiente_c: lectura.temp_ambiente_c,
    temp_agua_c: lectura.temp_agua_c,
    tds_ppm: lectura.tds_ppm,
    ph: lectura.ph,
    turbidez_ntu: lectura.turbidez_ntu
};
return msg;

const lectura = msg.lectura || {};
const diag = (msg.payload && typeof msg.payload === 'object') ? msg.payload : null;
const iaDisponible = !!diag && (typeof diag.es_anomalia !== 'undefined');

// --- Cálculo del Índice de Salud Hídrica (0 a 100) ---
function puntuar(valor, ideal_min, ideal_max, limite_min, limite_max) {
    if (valor >= ideal_min && valor <= ideal_max) return 100;
    if (valor < ideal_min) {
        if (valor <= limite_min) return 0;
        return Math.round(100 * (valor - limite_min) / (ideal_min - limite_min));
    }
    if (valor >= limite_max) return 0;
    return Math.round(100 * (limite_max - valor) / (limite_max - ideal_max));
}

const scorePh = puntuar(lectura.ph, 6.5, 8.5, 4.0, 11.0);
const scoreTds = puntuar(lectura.tds_ppm, 0, 500, 0, 1200);
const scoreTurbidez = puntuar(lectura.turbidez_ntu, 0, 50, 0, 600);
const scoreNivel = puntuar(lectura.nivel_m, 0.40, 3.0, 0.10, 5.0);

let saludHidrica = Math.round((scorePh + scoreTds + scoreTurbidez + scoreNivel) / 4);
if (iaDisponible && diag.es_anomalia) {
    saludHidrica = Math.min(saludHidrica, 35); // Penalización dura ante veredicto de IA
}

const fusion = {
    ...lectura,
    diagnostico: {
        ia_disponible: iaDisponible,
        es_anomalia: iaDisponible ? !!diag.es_anomalia : false,
        score: iaDisponible ? (diag.score !== undefined ? diag.score : null) : null
    },
    salud_hidrica_pct: saludHidrica
};

msg.payload = fusion;
return msg;

const MAX_BUFFER = 500;
const lectura = msg.payload;
if (!lectura || !lectura.nodo_id) return null;

let cache = global.get('telemetria_cache') || {};
cache[lectura.nodo_id] = lectura;
global.set('telemetria_cache', cache);

let series = global.get('series_buffer') || {};
if (!series[lectura.nodo_id]) series[lectura.nodo_id] = [];
series[lectura.nodo_id].push(lectura);
if (series[lectura.nodo_id].length > MAX_BUFFER) {
    series[lectura.nodo_id] = series[lectura.nodo_id].slice(-MAX_BUFFER);
}
global.set('series_buffer', series);

return msg;

let data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('Alerta MQTT con payload inválido: ' + msg.payload);
    return null;
}

const nodoId = msg.topic ? msg.topic.split('/').pop() : 'desconocido';

msg.payload = {
    nodo_id: nodoId,
    origen: 'motor_ia_chancay (MQTT directo)',
    severidad: (data.severidad || 'ALTA').toUpperCase() === 'ALTA' ? 'CRITICO' : 'ADVERTENCIA',
    tipo: data.comando || 'ANOMALIA_DETECTADA',
    mensaje: data.motivo || 'Anomalía crítica detectada por el motor de IA.',
    lectura: null
};
return msg;

const MAX_HIST = 2000;
const p = msg.payload || {};

let severidad = p.severidad || 'ADVERTENCIA';
let tipo = p.tipo || 'ANOMALIA_DETECTADA';
let mensaje = p.mensaje || 'Anomalía detectada por el sistema.';
const lectura = p.lectura;

// Reclasificación fina si contamos con la lectura física original
if (lectura) {
    if (lectura.nivel_m < 0.40) {
        severidad = 'CRITICO'; tipo = 'RIESGO_DESBORDE';
        mensaje = `Nivel del río crítico: ${lectura.nivel_m} m (< 0.40 m). Riesgo de desborde/huayco.`;
    } else if (lectura.turbidez_ntu > 500) {
        severidad = 'CRITICO'; tipo = 'ARRASTRE_SEDIMENTOS';
        mensaje = `Turbidez extrema: ${lectura.turbidez_ntu} NTU. Posible huayco / arrastre de sedimentos.`;
    } else if (lectura.tds_ppm > 500) {
        severidad = 'ADVERTENCIA'; tipo = 'CONTAMINACION_QUIMICA';
        mensaje = `TDS elevado: ${lectura.tds_ppm} ppm (> 500 ppm). Posible vertimiento químico/minero.`;
    } else if (lectura.ph < 6.5 || lectura.ph > 8.5) {
        severidad = 'ADVERTENCIA'; tipo = 'PH_FUERA_DE_RANGO';
        mensaje = `pH fuera de rango seguro: ${lectura.ph}.`;
    } else {
        severidad = 'ADVERTENCIA'; tipo = tipo || 'ANOMALIA_MULTIVARIABLE';
        mensaje = 'Isolation Forest detectó un patrón anómalo en la firma combinada de sensores.';
    }
}

const alerta = {
    id: `AL-${Date.now()}-${Math.floor(Math.random()*1000)}`,
    ts: Date.now(),
    fecha_iso: new Date().toISOString(),
    nodo_id: p.nodo_id || 'desconocido',
    severidad,
    tipo,
    mensaje,
    origen: p.origen || 'motor_ia_chancay (HTTP /diagnostico)',
    lectura: lectura || null,
    atendida: false
};

let historial = global.get('alertas_historial') || [];
historial.unshift(alerta);
if (historial.length > MAX_HIST) historial = historial.slice(0, MAX_HIST);
global.set('alertas_historial', historial);

msg.payload = alerta;
return msg;

msg.payload = {
    servicio: 'Yaku Qhawaq - API Node-RED',
    estado: 'operativo',
    ts: Date.now(),
    nodos_activos: Object.keys(global.get('telemetria_cache') || {}).length
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const cache = global.get('telemetria_cache') || {};
const nodoId = msg.req.query.nodo_id;

msg.payload = nodoId ? (cache[nodoId] || {}) : Object.values(cache);
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const series = global.get('series_buffer') || {};
const nodoId = msg.req.query.nodo_id || 'nodo_chancay_01';
const limit = parseInt(msg.req.query.limit) || 200;

const datos = (series[nodoId] || []).slice(-limit);
msg.payload = { nodo_id: nodoId, total: datos.length, datos };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const q = msg.req.query || {};
const params = new URLSearchParams();
if (q.desde) params.set('desde', q.desde);
if (q.hasta) params.set('hasta', q.hasta);
if (q.nodo_id) params.set('nodo_id', q.nodo_id);
params.set('limit', q.limit || '500');

msg.url = `${flow.get('MOTOR_IA_BASE_URL')}/telemetria/historico?${params.toString()}`;
return msg;

msg.payload = Array.isArray(msg.payload) ? msg.payload : [];
msg.headers = { 'Content-Type': 'application/json' };
return msg;

let historial = global.get('alertas_historial') || [];
const q = msg.req.query || {};

if (q.severidad) {
    historial = historial.filter(a => a.severidad === q.severidad.toUpperCase());
}
if (q.nodo_id) {
    historial = historial.filter(a => a.nodo_id === q.nodo_id);
}
const limit = parseInt(q.limit) || 100;

msg.payload = {
    total: historial.length,
    criticas: historial.filter(a => a.severidad === 'CRITICO').length,
    advertencias: historial.filter(a => a.severidad === 'ADVERTENCIA').length,
    alertas: historial.slice(0, limit)
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const NODOS_GIS = [
    { nodo_id: 'nodo_chancay_01', nombre: 'Puente Huando (Estación Principal)', lat: -11.4959, lng: -77.2072, estado_infraestructura: 'ACTIVO' },
    { nodo_id: 'nodo_chancay_02', nombre: 'Media Cuenca - Acos (Planificado)', lat: -11.3336, lng: -76.7864, estado_infraestructura: 'PLANIFICADO' },
    { nodo_id: 'nodo_chancay_03', nombre: 'Desembocadura - Chancay (Planificado)', lat: -11.5744, lng: -77.2694, estado_infraestructura: 'PLANIFICADO' }
];

const cache = global.get('telemetria_cache') || {};
msg.payload = NODOS_GIS.map(n => ({ ...n, ultima_lectura: cache[n.nodo_id] || null }));
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const cache = global.get('telemetria_cache') || {};
const lecturas = Object.values(cache);

const promedio = lecturas.length
    ? Math.round(lecturas.reduce((acc, l) => acc + (l.salud_hidrica_pct || 0), 0) / lecturas.length)
    : null;

let estado = 'SIN_DATOS';
if (promedio !== null) {
    if (promedio >= 75) estado = 'OPTIMO';
    else if (promedio >= 45) estado = 'ADVERTENCIA';
    else estado = 'CRITICO';
}

msg.payload = { salud_hidrica_pct: promedio, estado, nodos_evaluados: lecturas.length, ts: Date.now() };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

function toCsv(rows, columnas) {
    const escape = (v) => {
        if (v === null || v === undefined) return '';
        const s = String(v).replace(/"/g, '""');
        return /[,"\n]/.test(s) ? `"${s}"` : s;
    };
    const header = columnas.join(',');
    const body = rows.map(r => columnas.map(c => escape(r[c])).join(',')).join('\n');
    return header + '\n' + body;
}

const tipo = (msg.req.query.tipo || 'alertas').toLowerCase();
let csv, filename;

if (tipo === 'lecturas') {
    const nodoId = msg.req.query.nodo_id || 'nodo_chancay_01';
    const series = global.get('series_buffer') || {};
    const datos = (series[nodoId] || []).map(d => ({
        ts: new Date(d.ts).toISOString(), nodo_id: d.nodo_id, nivel_m: d.nivel_m,
        temp_ambiente_c: d.temp_ambiente_c, temp_agua_c: d.temp_agua_c,
        tds_ppm: d.tds_ppm, ph: d.ph, turbidez_ntu: d.turbidez_ntu,
        es_anomalia: d.diagnostico ? d.diagnostico.es_anomalia : false,
        salud_hidrica_pct: d.salud_hidrica_pct
    }));
    csv = toCsv(datos, ['ts','nodo_id','nivel_m','temp_ambiente_c','temp_agua_c','tds_ppm','ph','turbidez_ntu','es_anomalia','salud_hidrica_pct']);
    filename = `lecturas_${nodoId}_${Date.now()}.csv`;
} else {
    const historial = (global.get('alertas_historial') || []).map(a => ({
        id: a.id, fecha_iso: a.fecha_iso, nodo_id: a.nodo_id, severidad: a.severidad,
        tipo: a.tipo, mensaje: a.mensaje, origen: a.origen, atendida: a.atendida
    }));
    csv = toCsv(historial, ['id','fecha_iso','nodo_id','severidad','tipo','mensaje','origen','atendida']);
    filename = `alertas_chancay_huaral_${Date.now()}.csv`;
}

msg.payload = csv;
msg.headers = {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': `attachment; filename="${filename}"`
};
return msg;

msg.statusCode = 500;
msg.payload = { error: true, mensaje: (msg.error && msg.error.message) ? msg.error.message : 'Error interno del servidor.' };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const NODOS_VALIDOS = ['nodo_chancay_01','nodo_chancay_02','nodo_chancay_03'];
const ACTUADORES_VALIDOS = ['sirena','compuerta'];
const ACCIONES_VALIDAS = ['activar','desactivar'];

const body = msg.payload || {};
const { nodo_id, actuador, accion, operador } = body;

const errores = [];
if (!NODOS_VALIDOS.includes(nodo_id)) errores.push(`nodo_id inválido: ${nodo_id}`);
if (!ACTUADORES_VALIDOS.includes(actuador)) errores.push(`actuador inválido: ${actuador}`);
if (!ACCIONES_VALIDAS.includes(accion)) errores.push(`accion inválida: ${accion}`);

if (errores.length > 0) {
    msg.statusCode = 400;
    msg.payload = { error: true, detalles: errores };
    msg.headers = { 'Content-Type': 'application/json' };
    msg.comandoValido = false;
    return msg;
}

msg.comandoValido = true;
msg.comando = {
    id: `TC-${Date.now()}`,
    ts: Date.now(),
    nodo_id, actuador, accion,
    operador: operador || 'operador_no_identificado',
    origen: 'panel_telecontrol_manual'
};
msg.topic = `chancay/actuadores/comando/${nodo_id}`;
msg.payload = JSON.stringify(msg.comando);
return msg;

const MAX_HIST = 500;
let historial = global.get('telecontrol_historial') || [];
historial.unshift(msg.comando);
if (historial.length > MAX_HIST) historial = historial.slice(0, MAX_HIST);
global.set('telecontrol_historial', historial);

msg.statusCode = 200;
msg.payload = { ok: true, comando: msg.comando };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

msg.payload = {
    comando_id: msg.comando.id,
    nodo_id: msg.comando.nodo_id,
    actuador: msg.comando.actuador,
    accion: msg.comando.accion,
    operador: msg.comando.operador,
    origen: msg.comando.origen,
    ts_comando: msg.comando.ts
};
return msg;

if (msg.statusCode >= 200 && msg.statusCode < 300) {
    node.log(`Comando ${msg.payload && msg.payload.comando_id} persistido en motor_ia_chancay.`);
} else {
    node.warn('No se pudo persistir el comando de telecontrol en motor_ia_chancay (no crítico).');
}
return null;

const historial = global.get('telecontrol_historial') || [];
const limit = parseInt((msg.req.query || {}).limit) || 100;
msg.payload = historial.slice(0, limit);
msg.headers = { 'Content-Type': 'application/json' };
return msg;

msg.statusCode = 500;
msg.payload = { error: true, mensaje: (msg.error && msg.error.message) ? msg.error.message : 'Error interno del servidor.' };
msg.headers = { 'Content-Type': 'application/json' };
return msg;
